const fs = require('fs');

function extract(filePath) {
    const buffer = fs.readFileSync(filePath);
    // Parse ELF header
    const e_phoff = buffer.readBigUInt64LE(32);
    const e_phentsize = buffer.readUInt16LE(54);
    const e_phnum = buffer.readUInt16LE(56);

    const result = {};

    for (let i = 0; i < e_phnum; i++) {
        const offset = Number(e_phoff) + i * e_phentsize;
        const p_type = buffer.readUInt32LE(offset);
        if (p_type === 1) { // PT_LOAD
            const p_offset = Number(buffer.readBigUInt64LE(offset + 8));
            const p_vaddr = Number(buffer.readBigUInt64LE(offset + 16));
            const p_filesz = Number(buffer.readBigUInt64LE(offset + 32));

            const baseAddr = 0x400000 + p_vaddr;
            for (let off = 0; off < p_filesz; off += 4) {
                if (p_offset + off + 4 <= buffer.length) {
                    const val = buffer.readUInt32LE(p_offset + off);
                    const addr = baseAddr + off;
                    result[addr.toString()] = val;
                }
            }
        }
    }
    return result;
}

const res = extract(process.argv[2]);
console.log(JSON.stringify(res, null, 2));
EOF

